#' Get types (or groups) of regressors
#'
#' Generate string of names for the regressors used in the model fit for a given series.
#'
#' Version 1.1, 1/7/2026
#'
#' @param seas_obj \code{seas} object generated by the \code{seasonal} package for a single series.
#'        This is a required entry.
#' @param return_string Logical scalar; if TRUE, results returned as a character string (default).
#'                      Else, results returned as a character array.
#' @return Character string (or array if \code{return_string} is \code{TRUE}) containing a summary 
#'         of the regressor groups in the regARIMA model. 
#'         If no regressors in the model, the routine will return a blank character (or blank vector).
#'
#' @author Brian C. Monsell, \email{monsell.brian@@bls.gov} or \email{bcmonsell@@gmail.com}
#'
#' @examples 
#' air_seas <- seasonal::seas(AirPassengers, slidingspans = "", 
#'                   transform.function = "log", 
#'                   x11 = "", forecast.maxlead=36, 
#'                   check.print = c( "pacf", "pacfplot" ))
#' air_reg_group <- get_reg_group_string(air_seas)
#' air_reg_group_vec <- 
#'     get_reg_group_string(air_seas, return_string = FALSE)
#' @export
get_reg_group_string <- function(seas_obj = NULL, return_string = TRUE) {
    # Author: Brian C. Monsell (OEUS) Version 1.1, 1/7/2026
    
    # check if a value is specified for \code{seas_obj}
    if (is.null(seas_obj)) {
        cat("must specify a seas object")
		return(NULL)
    } else {
    # check if a seas object is specified for \code{seas_obj}
        if (!inherits(seas_obj, "seas")) {
			cat("First argument must be a seas object")
			return(NULL)
       }
    }
    
    # Extract number of regressors
    this_nreg <- seasonal::udg(seas_obj, "nreg")
    
    # Initialize string of regressor names
    reg_group_string <- " "
	reg_group_vec <- array(" ", dim = 1)
    
    # If number of regressors greater than zero, get index of \code{nreg} keyword in UDG output
    if (this_nreg > 0) {
        this_reg_index <- get_udg_index(seasonal::udg(seas_obj), "nreg")
		if (is.null(this_reg_index)) { return(NULL) }
        
        # split keywords into regressor names and types
        reg_names <- names(seas_obj$udg)[seq(1, this_nreg) + this_reg_index]
        reg_group_vec <- 
			unlist(strsplit(reg_names, "[$]"))[seq(1, (2 * this_nreg) - 1, 2)]
        
        # create string of regressors from vector \code{reg_vec}
        if (return_string) {
			reg_group_string <- paste(reg_group_vec, collapse = " ")
		}
    }
    
#   return string if \code{return_string) = \code{TRUE}, vector otherwise
    if (return_string) {
		return(reg_group_string)
	} else {
		return(reg_group_vec)
	}
}
